## The Fix

Here's the corrected implementation. I've used `sync.RWMutex` for better read concurrency, `sync/atomic` for stats, and `sync.Cond` for proper waiting:

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    loading   bool
    cond      *sync.Cond
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data     map[string]*CacheEntry
    mu       sync.RWMutex
    ttl      time.Duration
    loader   LoadFunc
    stats    Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Try read lock first
    c.mu.RLock()
    if entry, ok := c.data[key]; ok && time.Now().Before(entry.ExpiresAt) && !entry.loading {
        c.mu.RUnlock()
        atomic.AddInt64(&c.stats.Hits, 1)
        return entry.Value, nil
    }
    c.mu.RUnlock()

    // Need write lock for potential modification
    c.mu.Lock()

    // Double-check
    if entry, ok := c.data[key]; ok {
        if time.Now().Before(entry.ExpiresAt) && !entry.loading {
            c.mu.Unlock()
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
        if entry.loading {
            // Wait for load to complete
            for entry.loading {
                entry.cond.Wait() // Releases and reacquires lock
            }
            c.mu.Unlock()
            if entry.Value == nil {
                return nil, ctx.Err()
            }
            return entry.Value, nil
        }
        entry.loading = true
        entry.cond = sync.NewCond(&c.mu)
    } else {
        c.data[key] = &CacheEntry{
            loading: true,
            cond:    sync.NewCond(&c.mu),
        }
    }
    entry := c.data[key]
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        delete(c.data, key)
        entry.cond.Broadcast()
        c.mu.Unlock()
        return nil, err
    }

    entry.Value = value
    entry.ExpiresAt = time.Now().Add(c.ttl)
    entry.loading = false
    entry.cond.Broadcast()
    c.mu.Unlock()

    return value, nil
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
    }
}

func (c *Cache) Invalidate(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.data, key)
}

func (c *Cache) InvalidateAll() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data = make(map[string]*CacheEntry)
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var resultsMu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                resultsMu.Lock()
                results[k] = value
                resultsMu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanupLoop() {
    ticker := time.NewTicker(time.Minute)
    for range ticker.C {
        c.cleanup()
    }
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        if !entry.loading && now.After(entry.ExpiresAt) {
            delete(c.data, key)
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}

func (c *Cache) Refresh(ctx context.Context, key string) error {
    value, err := c.loader(ctx, key)
    if err != nil {
        return err
    }
    c.Set(key, value)
    return nil
}

func (c *Cache) LoadOrStore(ctx context.Context, key string, loader LoadFunc) (interface{}, error) {
    c.mu.Lock()
    if entry, ok := c.data[key]; ok && time.Now().Before(entry.ExpiresAt) {
        c.mu.Unlock()
        return entry.Value, nil
    }
    c.mu.Unlock()

    value, err := loader(ctx, key)
    if err != nil {
        return nil, err
    }
    c.Set(key, value)
    return value, nil
}
```

---

## Key Changes

1. **RWMutex** - Read operations can proceed concurrently
2. **sync.Cond** - Proper signaling instead of busy-wait polling  
3. **atomic operations** - Stats increments are now safe
4. **WaitGroup** - GetMulti actually waits for completion
5. **Consistent locking** - All map access protected
6. **No deadlocks** - Lock ordering is consistent, Cond.Wait releases lock

The cache stampede is solved by the loading flag with condition variable - only one goroutine loads while others wait efficiently.

